// Create a flow
fun countDown(from: Int): Flow<Int> = flow {
    for (i in from downTo 0) {
        delay(1000)
        emit(i)  // send value downstream
    }
}

// Collect it (terminal operator)
viewModelScope.launch {
    countDown(5).collect { value ->
        println(value)  // 5, 4, 3, 2, 1, 0
    }
}

// StateFlow — always has a value
private val _count = MutableStateFlow(0)
val count: StateFlow<Int> = _count.asStateFlow()

fun increment() { _count.update { it + 1 } }

// SharedFlow — for one-shot events
private val _events = MutableSharedFlow<UiEvent>()
val events: SharedFlow<UiEvent> = _events.asSharedFlow()

suspend fun showError(msg: String) {
    _events.emit(UiEvent.ShowSnackbar(msg))
}

// Collecting StateFlow in Compose
val count by viewModel.count.collectAsState()

// Search with debounce + flatMapLatest
searchQuery
    .debounce(300)           // wait 300ms after typing stops
    .filter { it.length > 2 } // ignore short queries
    .flatMapLatest { query ->
        repository.search(query) // cancel previous search
    }
    .collect { results -> _state.update { it.copy(results = results) } }

// Combine multiple flows
combine(userFlow, settingsFlow) { user, settings ->
    UiState(user = user, darkMode = settings.darkMode)
}.collect { state -> _uiState.value = state }

interface ProfileRepository {
    suspend fun loadProfile(id: String): Profile      // one value, then done

    fun observeProfile(id: String): Flow<Profile>     // a new value on every change
}

fun observeReports(): Flow<Report> = flow {
    while (true) {
        emit(parseReport(readFile()))   // runs on Dispatchers.IO (because of flowOn below)
        delay(5_000)
    }
}.flowOn(Dispatchers.IO)                // affects only the code above this line

viewModelScope.launch {                 // collector stays on Main
    observeReports().collect { show(it) }
}

flow { repeat(5) { emit(it); delay(100) } }
    .buffer()                        // producer no longer waits for the collector
    .collect { delay(300); println(it) }

flow { repeat(5) { emit(it); delay(100) } }
    .conflate()                      // slow collector skips values, sees the latest
    .collect { delay(300); println(it) }

queryFlow.collectLatest { query -> showResults(search(query)) } // previous search is cancelled

repository.observeOrders()
    .map { OrdersUi.Content(it) as OrdersUi }
    .onStart { emit(OrdersUi.Loading) }
    .catch { e -> emit(OrdersUi.Error(e.message)) }   // upstream errors only
    .onCompletion { cause -> log("finished, cause = $cause") }
    .collect { render(it) }                           // errors in here are NOT caught above

api.liveUpdates()
    .retryWhen { cause, attempt ->
        if (cause is IOException && attempt < 3) {
            delay(1_000L shl attempt.toInt())   // 1s, 2s, 4s
            true                                // retry
        } else {
            false                               // give up: the error reaches catch/collect
        }
    }
    .catch { showOfflineBanner() }
    .collect { render(it) }

fun SensorApi.readings(): Flow<Reading> = callbackFlow {
    val callback = object : SensorCallback {
        override fun onReading(reading: Reading) { trySend(reading) }
        override fun onError(error: Throwable) { close(error) }
    }
    register(callback)
    awaitClose { unregister(callback) }   // required: cleanup on cancellation
}.conflate()

fun searchAll(queries: List<String>): Flow<SearchResult> = channelFlow {
    queries.forEach { query ->
        launch {                                    // runs concurrently
            send(api.search(query))                 // send is safe from any child
        }
    }
} // completes after every child has finished

class OrdersViewModel(repository: OrderRepository) : ViewModel() {
    val uiState: StateFlow<OrdersUi> = repository.observeOrders()
        .map { OrdersUi.Content(it) as OrdersUi }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5_000),
            initialValue = OrdersUi.Loading
        )
}

class SaveViewModel : ViewModel() {
    private val _events = Channel<UiEvent>(Channel.BUFFERED)
    val events: Flow<UiEvent> = _events.receiveAsFlow()

    fun onSave() {
        viewModelScope.launch {
            repository.save()
            _events.send(UiEvent.Saved)      // held until the screen collects it
        }
    }
}
